-- DoctorTalk database schema. Existing installations are upgraded automatically by database.py.
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, date_of_birth TEXT, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'patient', specialization TEXT, license_number TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE login_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, email TEXT NOT NULL, login_timestamp TEXT NOT NULL DEFAULT (datetime('now')), ip_address TEXT, user_agent TEXT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, language TEXT DEFAULT 'en-IN', created_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE medical_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, filename TEXT NOT NULL, stored_path TEXT NOT NULL, extracted_text TEXT, analysis TEXT, status TEXT DEFAULT 'uploaded', created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY(patient_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, title TEXT NOT NULL, specialty TEXT, notes TEXT, appointment_time TEXT NOT NULL, status TEXT DEFAULT 'requested', room_id TEXT UNIQUE, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY(patient_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(doctor_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE video_signals (room_id TEXT PRIMARY KEY, offer TEXT, answer TEXT, caller_candidates TEXT DEFAULT '[]', callee_candidates TEXT DEFAULT '[]', created_at TEXT DEFAULT (datetime('now')));
